	if value, ok := values["due_date"]; ok && value != nil {
		s, ok := value.(string)
		if !ok {
			return errors.New("조치 기한은 RFC3339 일시로 입력하세요")
		}
		if s != "" {
			if _, err := time.Parse(time.RFC3339, s); err != nil {
				return errors.New("조치 기한은 시간대가 포함된 RFC3339 일시로 입력하세요")
			}
		}
	}
	return nil
}

